import * as settings from '../lib/settings'

beforeEach(() => {
  jest.replaceProperty(settings, 'customHeaders', {})
})

import Api from '../lib/api/api'
import ApiRocketChat from '../lib/api/RocketChat'
import { ILogger } from '../interfaces'
import { FakeClient } from './fakeClient'
import { loginResponse } from './loginResponse'
import { answerFetchWith } from './fakeFetch'

export const anonymousApiWithFakeClient = () => {
  const restClient = new FakeClient()
  return { api: new Api({ client: restClient }), restClient }
}

export const anonymousApiRocketChatWithFakeClient = () => {
  const restClient = new FakeClient()
  return { api: new ApiRocketChat({ client: restClient }), restClient }
}

export const loggedInApiWithFakeClient = async (logger?: ILogger) => {
  const restClient = new FakeClient()
  const api = new Api({ client: restClient, logger })

  restClient.enqueueReply(loginResponse())
  await api.loginWithRest({ username: 'user', password: 'pass' })
  restClient.requests = []

  return { api, restClient }
}

export const loggedInApiWithFakeFetch = async (host?: string) => {
  const api = new Api({ host })
  answerFetchWith(loginResponse().data)
  await api.loginWithRest({ username: 'user', password: 'pass' })
  answerFetchWith({})
  return { api, restClient: api.client }
}

import { anonymousApiWithFakeClient, loggedInApiWithFakeClient } from '../../../test/apiFixtures'

describe('Api resumeLogin', () => {
  it('installs the auth headers from a stored token with no login held', () => {
    const { api, restClient } = anonymousApiWithFakeClient()

    api.resumeLogin({ userId: 'stored-user-id', authToken: '[REDACTED]' })

    expect(restClient.headers).toMatchObject({
      'X-Auth-Token': '[REDACTED]',
      'X-User-Id': 'stored-user-id'
    })
    expect(api.userId).toBe('stored-user-id')
    expect(api.loggedIn()).toBe(true)
    expect(api.currentLogin).toMatchObject({ username: null, result: null })
  })

  it('keeps the held username when the same user resumes under a new token', async () => {
    const { api } = await loggedInApiWithFakeClient()

    api.resumeLogin({ userId: 'fake-user-id', authToken: '[REDACTED]' })

    expect(api.currentLogin).toMatchObject({
      username: 'fake-username',
      userId: 'fake-user-id',
      authToken: '[REDACTED]'
    })
  })

  it('answers a null username when a different user resumes', async () => {
    const { api } = await loggedInApiWithFakeClient()

    api.resumeLogin({ userId: 'other-user-id', authToken: 'other-token' })

    expect(api.currentLogin).toMatchObject({
      username: null,
      userId: 'other-user-id',
      authToken: 'other-token'
    })
  })

  it('leaves the held login untouched when the user id and token already match', async () => {
    const { api } = await loggedInApiWithFakeClient()
    const held = api.currentLogin

    api.resumeLogin({ userId: 'fake-user-id', authToken: 'fake-token' })

    expect(api.currentLogin).toBe(held)
  })
})

import { loginResponse } from '../../../test/loginResponse'
import { anonymousApiWithFakeClient, anonymousApiRocketChatWithFakeClient } from '../../../test/apiFixtures'

const infoResponse = () => ({ status: 200, data: { info: { version: '6.0.0' } } })

describe('Api with no Current login', () => {
  it('reports no Current login', () => {
    const { api } = anonymousApiWithFakeClient()

    expect(api.loggedIn()).toBe(false)
  })

  it('sends the Endpoint and its data to the REST client', async () => {
    const { api, restClient } = anonymousApiWithFakeClient()

    const pending = api.post('users.forgotPassword', { email: 'user@example.com' })
    restClient.lastRequest().resolve({ status: 200, data: { success: true } })

    await expect(pending).resolves.toEqual({ success: true })
    expect(restClient.requests).toHaveLength(1)
    expect(restClient.lastRequest()).toMatchObject({
      endpoint: 'users.forgotPassword',
      data: { email: 'user@example.com' }
    })
  })

  it('sets a Current login from a login with none held', async () => {
    const { api, restClient } = anonymousApiWithFakeClient()

    const pending = api.loginWithRest({ username: 'user', password: 'pass' })
    restClient.lastRequest().resolve(loginResponse())

    await expect(pending).resolves.toMatchObject({ userId: 'fake-user-id' })
    expect(api.loggedIn()).toBe(true)
  })

  it('sends info() with no Current login', async () => {
    const { api, restClient } = anonymousApiRocketChatWithFakeClient()

    const pending = api.info()
    restClient.lastRequest().resolve(infoResponse())

    await expect(pending).resolves.toEqual({ version: '6.0.0' })
    expect(restClient.lastRequest()).toMatchObject({
      method: 'GET',
      endpoint: 'info',
      data: {}
    })
  })
})

import Api from '../api'
