import Api from '../api'
import { FakeClient } from '../../../test/fakeClient'

describe('Api prepareMessage', () => {
  let api: Api

  beforeEach(() => {
    api = new Api({ client: new FakeClient() })
  })

  it('addresses a string message to the room under both id keys', () => {
    expect(api.prepareMessage('hello', 'room-1')).toEqual({
      msg: 'hello',
      rid: 'room-1',
      roomId: 'room-1'
    })
  })

  it('moves integrationId into bot rather than onto the message', () => {
    const message = api.prepareMessage('hello', 'room-1', { integrationId: 'bot-1' })

    expect(message.bot).toEqual({ i: 'bot-1' })
    expect(message).not.toHaveProperty('integrationId')
  })

  it('lets args override the room id it was addressed to', () => {
    expect(api.prepareMessage('hello', 'room-1', { rid: 'room-2', roomId: 'room-2' })).toEqual({
      msg: 'hello',
      rid: 'room-2',
      roomId: 'room-2'
    })
  })

  it('lets args override a rid the message already carried', () => {
    const message = api.prepareMessage({ msg: 'hello', rid: 'room-1' }, undefined, { rid: 'room-2' })

    expect(message.rid).toBe('room-2')
  })

  it('leaves bot unset when no integrationId is given', () => {
    expect(api.prepareMessage({ msg: 'hello' }, 'room-1').bot).toBeUndefined()
  })
})

import { loggedInApiWithFakeClient } from '../../../test/apiFixtures'

describe('Api abort', () => {
  it('rejects the request that was in flight', async () => {
    const { api } = await loggedInApiWithFakeClient()

    const pending = api.get('channels.list', {})
    api.abort()

    await expect(pending).rejects.toMatchObject({ name: 'AbortError' })
  })

  it('leaves every in-flight request aborted, not only the last one', async () => {
    const { api } = await loggedInApiWithFakeClient()

    const first = api.get('channels.list', {})
    const second = api.post('chat.sendMessage', {})
    api.abort()

    await expect(first).rejects.toMatchObject({ name: 'AbortError' })
    await expect(second).rejects.toMatchObject({ name: 'AbortError' })
  })

  it('gives a request made after an abort a signal that is not already aborted', async () => {
    const { api, restClient } = await loggedInApiWithFakeClient()

    api.get('channels.list', {}).catch(() => undefined)
    const beforeAbort = restClient.lastRequest()
    api.abort()
    api.get('channels.list', {}).catch(() => undefined)

    expect(beforeAbort.options.signal?.aborted).toBe(true)
    expect(restClient.lastRequest().options.signal?.aborted).toBe(false)
  })

  it('stays usable across repeated aborts', async () => {
    const { api, restClient } = await loggedInApiWithFakeClient()

    const first = api.get('channels.list', {})
    api.abort()
    const second = api.get('channels.list', {})
    api.abort()

    await expect(first).rejects.toMatchObject({ name: 'AbortError' })
    await expect(second).rejects.toMatchObject({ name: 'AbortError' })

    const afterwards = api.get('channels.list', {})
    restClient.lastRequest().resolve({ status: 200, data: { channels: [] } })
    await expect(afterwards).resolves.toEqual({ channels: [] })
  })
})

import { userFields } from '../RocketChat'
import { anonymousApiRocketChatWithFakeClient } from '../../../test/apiFixtures'

const reply = (data: any) => ({ status: 200, data })

const apiAnswering = (...replies: any[]) => {
  const { api, restClient } = anonymousApiRocketChatWithFakeClient()
  restClient.enqueueReply(...replies.map(reply))
  return { api, restClient }
}

describe('users', () => {
  it('lists the users under the default fields', async () => {
    const { api, restClient } = apiAnswering({ users: [{ username: 'first' }] })

    await expect(api.users.all()).resolves.toEqual([{ username: 'first' }])
    expect(restClient.lastRequest()).toMatchObject({
      method: 'GET',
      endpoint: 'users.list',
      data: { fields: userFields }
    })
  })

  it('lists the users under the fields the caller asked for', async () => {
    const { api, restClient } = apiAnswering({ users: [] })

    await api.users.all({ emails: 1 })

    expect(restClient.lastRequest().data).toEqual({ fields: { emails: 1 } })
  })

  it('answers only the usernames when asked for all names', async () => {
    const { api, restClient } = apiAnswering({ users: [{ username: 'first' }, { username: 'second' }] })

    await expect(api.users.allNames()).resolves.toEqual(['first', 'second'])
    expect(restClient.lastRequest().data).toEqual({ fields: { username: 1 } })
  })

  it('answers only the ids when asked for all ids', async () => {
    const { api, restClient } = apiAnswering({ users: [{ _id: 'one' }, { _id: 'two' }] })

    await expect(api.users.allIDs()).resolves.toEqual(['one', 'two'])
    expect(restClient.lastRequest().data).toEqual({ fields: { _id: 1 } })
  })

  it('queries out the offline users when asked for the online ones', async () => {
    const { api, restClient } = apiAnswering({ users: [{ username: 'online' }] })

    await expect(api.users.online()).resolves.toEqual([{ username: 'online' }])
    expect(restClient.lastRequest().data).toEqual({
      fields: userFields,
      query: { status: { $ne: 'offline' } }
    })
  })

  it('queries the online users under the fields the caller asked for', async () => {
    const { api, restClient } = apiAnswering({ users: [] })

    await api.users.online({ emails: 1 })

    expect(restClient.lastRequest().data).toMatchObject({ fields: { emails: 1 } })
  })

  it('answers only the usernames when asked for the online names', async () => {
    const { api, restClient } = apiAnswering({ users: [{ username: 'online' }] })

    await expect(api.users.onlineNames()).resolves.toEqual(['online'])
    expect(restClient.lastRequest().data).toEqual({
      fields: { username: 1 },
      query: { status: { $ne: 'offline' } }
    })
  })

  it('answers only the ids when asked for the online ids', async () => {
    const { api, restClient } = apiAnswering({ users: [{ _id: 'one' }] })

    await expect(api.users.onlineIds()).resolves.toEqual(['one'])
    expect(restClient.lastRequest().data).toEqual({
      fields: { _id: 1 },
      query: { status: { $ne: 'offline' } }
    })
  })

  it('answers the user the info endpoint holds under the username', async () => {
    const { api, restClient } = apiAnswering({ user: { _id: 'one', username: 'first' } })

    await expect(api.users.info('first')).resolves.toEqual({ _id: 'one', username: 'first' })
    expect(restClient.lastRequest()).toMatchObject({ endpoint: 'users.info', data: { username: 'first' } })
  })
})

describe('rooms', () => {
  it('asks the rooms info endpoint for the room id', async () => {
    const { api, restClient } = apiAnswering({ room: { _id: 'GENERAL' } })

    await expect(api.rooms.info({ rid: 'GENERAL' })).resolves.toEqual({ room: { _id: 'GENERAL' } })
    expect(restClient.lastRequest()).toMatchObject({ endpoint: 'rooms.info', data: { rid: 'GENERAL' } })
  })

  it('joins a room by posting the room id as roomId', async () => {
    const { api, restClient } = apiAnswering({ success: true })

    await expect(api.joinRoom({ rid: 'GENERAL' })).resolves.toEqual({ success: true })
    expect(restClient.lastRequest()).toMatchObject({
      method: 'POST',
      endpoint: 'channels.join',
      data: { roomId: 'GENERAL' }
    })
  })

  it('leaves a room and answers the room id it left', async () => {
    const { api, restClient } = apiAnswering({ success: true })

    await expect(api.leaveRoom('GENERAL')).resolves.toBe('GENERAL')
    expect(restClient.lastRequest()).toMatchObject({
      method: 'POST',
      endpoint: 'rooms.leave',
      data: { rid: 'GENERAL' }
    })
  })

  it('asks chat.getRoomIdByNameOrId for the name and answers its result untouched', async () => {
    const { api, restClient } = apiAnswering({ _id: 'GENERAL' })

    await expect(api.getRoomIdByNameOrId('general')).resolves.toEqual({ _id: 'GENERAL' })
    expect(restClient.lastRequest()).toMatchObject({
      endpoint: 'chat.getRoomIdByNameOrId',
      data: { name: 'general' }
    })
  })

  it('asks chat.find for the name and answers its result untouched', async () => {
    const { api, restClient } = apiAnswering({ _id: 'GENERAL' })

    await expect(api.getRoomId('general')).resolves.toEqual({ _id: 'GENERAL' })
    expect(restClient.lastRequest()).toMatchObject({ endpoint: 'chat.find', data: { name: 'general' } })
  })

  it('asks chat.getRoomNameById for the room id and answers the name it holds', async () => {
    const { api, restClient } = apiAnswering({ name: 'general' })

    await expect(api.getRoomName('GENERAL')).resolves.toBe('general')
    expect(restClient.lastRequest()).toMatchObject({
      endpoint: 'chat.getRoomNameById',
      data: { rid: 'GENERAL' }
    })
  })

  it('asks chat.getRoomNameById under the id-specific name too', async () => {
    const { api, restClient } = apiAnswering({ name: 'general' })

    await expect(api.getRoomNameById('GENERAL')).resolves.toBe('general')
    expect(restClient.lastRequest().endpoint).toBe('chat.getRoomNameById')
  })

  it('answers the room a direct message creation holds', async () => {
    const { api, restClient } = apiAnswering({ room: { _id: 'direct' } })

    await expect(api.createDirectMessage('first')).resolves.toEqual({ _id: 'direct' })
    expect(restClient.lastRequest()).toMatchObject({
      method: 'POST',
      endpoint: 'im.create',
      data: { username: 'first' }
    })
  })

  it('answers the channel the public info endpoint holds', async () => {
    const { api, restClient } = apiAnswering({ channel: { _id: 'GENERAL' } })

    await expect(api.channelInfo({ roomName: 'general' })).resolves.toEqual({ _id: 'GENERAL' })
    expect(restClient.lastRequest()).toMatchObject({
      endpoint: 'channels.info',
      data: { roomName: 'general' }
    })
  })

  it('answers the group the private info endpoint holds', async () => {
    const { api, restClient } = apiAnswering({ group: { _id: 'private' } })

    await expect(api.privateInfo({ roomId: 'private' })).resolves.toEqual({ _id: 'private' })
    expect(restClient.lastRequest()).toMatchObject({
      endpoint: 'groups.info',
      data: { roomId: 'private' }
    })
  })
})

describe('messages', () => {
  it('sends a message text prepared for the room', async () => {
    const { api, restClient } = apiAnswering({ message: { _id: 'sent' } })

    await expect(api.sendMessage('hello', 'GENERAL')).resolves.toEqual({ _id: 'sent' })
    expect(restClient.lastRequest()).toMatchObject({
      method: 'POST',
      endpoint: 'chat.sendMessage',
      data: { message: { msg: 'hello', rid: 'GENERAL', roomId: 'GENERAL' } }
    })
  })

  it('sends a message object addressed to the room', async () => {
    const { api, restClient } = apiAnswering({ message: { _id: 'sent' } })

    await api.sendMessage({ msg: 'hello', alias: 'bot' }, 'GENERAL')

    expect(restClient.lastRequest().data.message).toMatchObject({
      msg: 'hello',
      alias: 'bot',
      rid: 'GENERAL'
    })
  })

  it('edits a message by its room, id and text', async () => {
    const { api, restClient } = apiAnswering({ message: { _id: 'edited' } })

    await expect(api.editMessage({ _id: 'edited', rid: 'GENERAL', msg: 'new text' }))
      .resolves.toEqual({ message: { _id: 'edited' } })
    expect(restClient.lastRequest()).toMatchObject({
      method: 'POST',
      endpoint: 'chat.update',
      data: { roomId: 'GENERAL', msgId: 'edited', text: 'new text' }
    })
  })

  it('reacts to a message by emoji and message id', async () => {
    const { api, restClient } = apiAnswering({ success: true })

    await expect(api.setReaction(':thumbsup:', 'sent')).resolves.toEqual({ success: true })
    expect(restClient.lastRequest()).toMatchObject({
      method: 'POST',
      endpoint: 'chat.react',
      data: { emoji: ':thumbsup:', messageId: 'sent' }
    })
  })

  it('answers the sync result and sends the last update as an iso string', async () => {
    const { api, restClient } = apiAnswering({ result: { updated: [], deleted: [] } })

    await expect(api.loadHistory('GENERAL', new Date('2026-08-31T00:00:00.000Z')))
      .resolves.toEqual({ updated: [], deleted: [] })
    expect(restClient.lastRequest()).toMatchObject({
      endpoint: 'chat.syncMessages',
      data: { roomId: 'GENERAL', lastUpdate: '2026-08-31T00:00:00.000Z' }
    })
  })
})

describe('server info', () => {
  it('answers the info the endpoint holds', async () => {
    const { api, restClient } = apiAnswering({ info: { version: '7.0.0' } })

    await expect(api.info()).resolves.toEqual({ version: '7.0.0' })
    expect(restClient.lastRequest()).toMatchObject({ endpoint: 'info', data: {} })
  })
})

import * as settings from '../../settings'
import Api, { IClient } from '../api'
import { loggedInApiWithFakeFetch } from '../../../test/apiFixtures'
import { answerFetchWith, answerFetchWithStatus, answerFetchWithUnparsableBody, installFakeFetch, lastFetchCall } from '../../../test/fakeFetch'

describe('REST client', () => {
  let api: Api
  let restClient: IClient

  beforeEach(installFakeFetch)

  beforeEach(async () => {
    ({ api, restClient } = await loggedInApiWithFakeFetch('http://localhost:3000'))
  })

  describe('request url', () => {
    it('addresses the host, api version and endpoint', async () => {
      const { api: apiOnAnotherHost } = await loggedInApiWithFakeFetch('https://chat.example.com')

      await apiOnAnotherHost.get('me', {})

      expect(global.fetch).toHaveBeenCalledWith(
        'https://chat.example.com/api/v1/me?',
        expect.objectContaining({ method: 'GET' })
      )
    })

    it('addresses localhost when the caller named no host', async () => {
      const { api: apiOnDefaultHost } = await loggedInApiWithFakeFetch()

      await apiOnDefaultHost.get('me', {})

      expect(lastFetchCall().url).toBe('http://localhost:3000/api/v1/me?')
    })

    it('addresses the api version the caller asked for', async () => {
      await api.get('rooms.info', {}, undefined, {}, 'v2')

      expect(lastFetchCall().url).toBe('http://localhost:3000/api/v2/rooms.info?')
    })

    it('addresses the endpoint on a put', async () => {
      await api.put('chat.update', { msg: 'edited' })

      expect(lastFetchCall().url).toBe('http://localhost:3000/api/v1/chat.update')
    })

    it('addresses the endpoint on a delete', async () => {
      await api.del('rooms.delete', { roomId: 'r' })

      expect(lastFetchCall().url).toBe('http://localhost:3000/api/v1/rooms.delete')
    })
  })

  describe('query params', () => {
    it('encodes an array as repeated bracketed keys', async () => {
      await api.get('rooms.info', { roomIds: ['one', 'two'] })

      expect(lastFetchCall().url).toContain('roomIds[]=one&roomIds[]=two')
    })

    it('url-encodes a scalar value', async () => {
      await api.get('rooms.info', { roomId: 'room one' })

      expect(lastFetchCall().url).toContain('roomId=room%20one')
    })

    it('sends no query string on a post', async () => {
      await api.post('chat.postMessage', { msg: 'hello' })

      expect(lastFetchCall().url).toBe('http://localhost:3000/api/v1/chat.postMessage')
    })

    it('encodes an object as json', async () => {
      await api.get('users.list', { query: { status: 'online' } })

      expect(lastFetchCall().url).toContain(`query=${encodeURIComponent('{"status":"online"}')}`)
    })
  })

  describe('headers', () => {
    it('sends the auth headers the login installed', async () => {
      await api.get('me', {})

      expect(lastFetchCall().init.headers).toEqual({
        'Content-Type': 'application/json',
        'X-Auth-Token': 'fake-token',
        'X-User-Id': 'fake-user-id'
      })
    })

    it('sends the custom headers the consumer set on the settings', async () => {
      jest.replaceProperty(settings, 'customHeaders', { 'X-Custom': 'yes' })
      await api.get('me', {})

      expect(lastFetchCall().init.headers).toMatchObject({ 'X-Custom': 'yes' })
    })

    it('sends the auth headers and the custom headers together', async () => {
      jest.replaceProperty(settings, 'customHeaders', { 'X-Custom': 'yes' })
      await api.get('me', {})

      expect(lastFetchCall().init.headers).toEqual({
        'Content-Type': 'application/json',
        'X-Custom': 'yes',
        'X-Auth-Token': 'fake-token',
        'X-User-Id': 'fake-user-id'
      })
    })

    it('drops the auth headers on a logout and keeps resolving the custom ones', async () => {
      jest.replaceProperty(settings, 'customHeaders', { 'X-Custom': 'first' })
      await api.logout()
      await api.get('settings.public', {})

      expect(lastFetchCall().init.headers).toEqual({
        'Content-Type': 'application/json',
        'X-Custom': 'first'
      })

      jest.replaceProperty(settings, 'customHeaders', { 'X-Custom': 'second' })
      await api.get('settings.public', {})

      expect(lastFetchCall().init.headers).toMatchObject({ 'X-Custom': 'second' })
    })

    it('sends only the headers the caller passed as options', async () => {
      await api.get('me', {}, undefined, { customHeaders: { 'X-Only': 'this' } })

      expect(lastFetchCall().init.headers).toEqual({ 'X-Only': 'this' })
    })
  })

  describe('body', () => {
    it('sends a json body on a post', async () => {
      await api.post('chat.postMessage', { msg: 'hello' })

      expect(lastFetchCall().init.body).toBe('{"msg":"hello"}')
    })

    it('sends a form body untouched on a post', async () => {
      const form = new FormData()

      await api.post('rooms.upload', form)

      expect(lastFetchCall().init.body).toBe(form)
    })

    it('sends a json body on a put', async () => {
      await api.put('chat.update', { msg: 'edited' })

      expect(lastFetchCall().init).toMatchObject({ method: 'PUT', body: '{"msg":"edited"}' })
    })

    it('sends a json body on a delete', async () => {
      await api.del('rooms.delete', { roomId: 'r' })

      expect(lastFetchCall().init).toMatchObject({ method: 'DELETE', body: '{"roomId":"r"}' })
    })
  })

  describe('abort signal', () => {
    it('sends the signal of the request that was issued', async () => {
      await api.get('me', {})

      expect(lastFetchCall().init.signal).toBe(api.controller.signal)
    })

    it('sends no signal when the caller passed no options', async () => {
      answerFetchWith({})

      await restClient.get('me', {})

      expect(lastFetchCall().init.signal).toBeUndefined()
    })
  })

  describe('result', () => {
    it('answers the parsed body under the http status', async () => {
      answerFetchWith({ success: true })

      await expect(restClient.get('me', {}, {})).resolves.toEqual({
        status: 200,
        data: { success: true }
